{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.WillHeadlee/lgl-mcp-server",
  "description": "MCP server for Little Green Light CRM. Search donors, log gifts, manage groups and contacts.",
  "repository": {
    "url": "https://github.com/WillHeadlee/Little-Green-Light-MCP-Server",
    "source": "github"
  },
  "version": "1.2.0",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "lgl-mcp-server",
      "version": "1.2.0",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "LGL_API_KEY",
          "description": "Your Little Green Light API key (Settings → Integration → API Keys)",
          "isRequired": true,
          "isSecret": true,
          "format": "string"
        },
        {
          "name": "LGL_READ_ONLY",
          "description": "Set to \"true\" to refuse all create/update/delete tool calls and hide mutation tools from tools/list. Useful when pointing the server at a live donor database from an exploratory session.",
          "isRequired": false,
          "isSecret": false,
          "format": "string"
        }
      ]
    }
  ]
}
